import http from 'http';
import axios from '/testbed/index.js';
const srv = http.createServer((req, res) => {
  let b = '';
  req.on('data', d => { b += d; });
  req.on('end', () => res.end(JSON.stringify({h: req.headers, b})));
}).listen(0, async () => {
  const fd = new FormData();
  fd.append('a', '1');
  fd.append('f', new Blob(['hello'], {type: 'text/plain'}), 'x.txt');
  const r = await axios.post('http://localhost:' + srv.address().port, fd, {headers: {'Content-Type': 'multipart/form-data'}});
  console.log(r.data.h['content-type'], r.data.h['content-length'], Buffer.byteLength(r.data.b));
  console.log(r.data.b);
  srv.close();
});

